template:
mod bank {
    pub struct Account {
        balance: i64,
    }

    impl Account {
        pub fn open(initial: i64) -> Account {
            Account { balance: initial }
        }

        pub fn balance(&self) -> i64 {
            self.balance
        }
    }
}

fn main() {
    let acc = ⟦slot1⟧::⟦slot2⟧(100);
    assert_eq!(acc.balance(), 100);
}

tests:
#[test]
fn test_account_open() {
    let acc = bank::Account::open(100);
    assert_eq!(acc.balance(), 100);
}
